import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as a,c as n,o as s,ag as e,G as l}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Google Flow","description":"Google 的 AI 创意工作室。用英文提示词生成几秒到十几秒的视频片段，再用 Scenebuilder 排成一部成片。本页讲清能不能用、10 分钟怎么做出第一段、积分怎么扣、常见坑怎么躲。","frontmatter":{"title":"Google Flow","description":"Google 的 AI 创意工作室。用英文提示词生成几秒到十几秒的视频片段，再用 Scenebuilder 排成一部成片。本页讲清能不能用、10 分钟怎么做出第一段、积分怎么扣、常见坑怎么躲。","domain":"product","tags":["coding-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/gemini/flow.md","filePath":"zh/products/gemini/flow.md","lastUpdated":1795592559000}'),i={name:"zh/products/gemini/flow.md"};function d(g,t,h,p,c,u){const o=a("DocDiagram");return s(),n("div",null,[t[0]||(t[0]=e("",52)),l(o,{src:"/diagrams/google-flow-pipeline.svg",alt:"这张图从左到右分四段，回答一个问题：你输入的一句话、一张参考图，分别被哪个模型接手，最后怎么变成时间线上的一个片段。第一段是输入，有三样：文字提示、参考帧（start frame 与 end frame）、参考素材（角色、场景、物件）。第二段是模型。视频模型有两个，Gemini Omni 的 Omni Flash 与 Veo 3.1 的 Veo 3.1 Lite，负责视频生成、视频编辑与对话式迭代，每次生成都消耗积分，按秒或按次计算。图片模型是 Nano Banana 系列（Pro、2.1、2 Lite），负责图片生成与编辑，不消耗积分，走每日上限。第三段是产出：视频模型产出候选片段，图片模型产出图片。第四段是成片，也就是 Scenebuilder 的时间线。连线有六组。第一，文字提示直接进入视频模型。第二，参考帧和参考素材可以随同一次生成一起进入视频模型。第三，视频模型产出候选片段，图片模型产出图片。第四，从候选片段到 Scenebuilder 的箭头标着 Add to Scene，只有你挑中的候选才进入时间线，没挑中的不进入。第五，底部一条向左的虚线从产出的图片回到输入：生成的图片可以再当作后续视频生成的 start frame、end frame 或 ingredient。第六，模型层与 Scenebuilder 之间顶部的双向虚线是 Extend：从已有片段的末尾回到视频模型，生成续接片段后再回到时间线。Scenebuilder 内部，片段按顺序排列，可以拖动调整顺序，可以修剪首尾。本图省略了每个生成模式各自支持哪些模型的对照，因为同一个生成模式往往有多个模型都支持，所以输入到模型之间没有画成一对一；也省略了具体的积分数字、API 调用路径，以及积分体系分开的 Flow Music。",width:1080}),t[1]||(t[1]=e("",146))])}const y=r(i,[["render",d]]);export{k as __pageData,y as default};
